meta.acceptance:
D=/tmp/morph/document-p7; mkdir -p $D; S=$(date +%s)-$$; L=$D/acc-$S.log
cp src/cli/types.ts $D/0-$S.ts 2>/dev/null
cp src/cli/document.ts $D/1-$S.ts 2>/dev/null
(
 set -e
 export NO_COLOR=1 CI=1
P=$PWD/probe/document; rm -rf $P; mkdir -p $P; trap 'rm -rf $P' EXIT
cat > $P/guard.mjs <<'MORPH_GUARD_EOF'
// MorphV2 guard: the layer rules of docs/CONVENTIONS.md and the test-file rules, checked on
// the TypeScript syntax tree. Inlined into every acceptance by decks/tools/build.py.
//   node guard.mjs src [file,file,...]                   every .ts under src/, or only these
//   node guard.mjs helpers <file> <name,name,...>        the stub module: node:* only, exports
//   node guard.mjs tests <file> <min> <max> [lits.json]  one test file; lits = strings it must hold
import ts from "typescript";
import fs from "node:fs";
import path from "node:path";

const bad = [];

// which internal layers a layer may import; "*" = any; unknown dirs are reported
const LAYERS = {
  cards: [], wait: [],
  response: ["cards"], store: ["cards"], compiler: ["cards"], language: ["cards"],
  contour: ["cards"], git: ["cards"], acceptance: ["cards", "wait", "compiler"],
  processor: ["cards", "wait", "compiler"], planner: ["cards", "contour", "language"],
  primer: ["cards", "git", "store", "language"],
  scout: ["cards", "processor", "wait", "primer"],
  reviewer: ["cards", "contour", "primer", "scout", "git"],
  runloop: ["cards", "wait", "store", "compiler", "response", "acceptance", "language",
    "git", "processor"],
  cli: "*",
};
const ROOT_FILES = new Set(["src/index.ts"]);
const SHELL = new Set(["acceptance", "git"]);          // node:child_process
const NET = new Set(["processor"]);                    // fetch, WebSocket, XMLHttpRequest
const CONSOLE = new Set(["cli"]);                      // console, process.exit
const PROCESS = new Set(["cli", "processor", "acceptance"]);
const NO_CLOCK = new Set(["cards", "compiler", "response", "language", "contour", "planner"]);
const YAML = new Set(["contour"]);
// P3: the acceptance gets the child's environment as a parameter (docs/TASK_P3_acceptance.md §4)
const NO_ENV = new Set(["acceptance", "processor", "git"]);
// P4: the one file of a NO_ENV layer that may read process.env (Read Registry, docs/TASK_P4_processor.md §4)
const ENV_READERS = new Set(["src/processor/registry.ts"]);
// P6: the one file of src/git that spawns (Run Git, docs/TASK_P6_git.md §4); git takes the env whole
const GIT_SPAWNER = "src/git/run.ts";
// P7: the binary's entry is src/cli.ts (package.json bin dist/cli.js), layer cli; it alone touches
// process (env, argv, cwd, stdout, exitCode) and the wall clock: src/cli/* gets them as parameters
// (docs/TASK_P7_cli.md §4)
const CLI_ENTRY = "src/cli.ts";

function parse(file) {
  return ts.createSourceFile(file, fs.readFileSync(file, "utf8"), ts.ScriptTarget.Latest, true,
    ts.ScriptKind.TS);
}
function line(sf, node) {
  return sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
}
function report(sf, node, rule) {
  bad.push(`guard: ${sf.fileName}:${line(sf, node)} ${rule}`);
}
function walk(node, fn) {
  fn(node);
  ts.forEachChild(node, (child) => walk(child, fn));
}
// an identifier that refers to a value binding (not a property name, a type, a declared name)
function isValueRef(node) {
  const p = node.parent;
  if (!p) return false;
  if (ts.isPropertyAccessExpression(p) && p.name === node) return false;
  if ((ts.isPropertyAssignment(p) || ts.isPropertyDeclaration(p) || ts.isPropertySignature(p) ||
       ts.isMethodDeclaration(p) || ts.isMethodSignature(p) || ts.isGetAccessor(p) ||
       ts.isSetAccessor(p) || ts.isEnumMember(p)) && p.name === node) return false;
  if (ts.isTypeReferenceNode(p) || ts.isQualifiedName(p) || ts.isTypeQueryNode(p)) return false;
  if ((ts.isParameter(p) || ts.isVariableDeclaration(p) || ts.isFunctionDeclaration(p) ||
       ts.isBindingElement(p)) && p.name === node) return false;
  if (ts.isImportSpecifier(p) || ts.isExportSpecifier(p) || ts.isImportClause(p)) return false;
  if (ts.isLabeledStatement(p) || ts.isBreakOrContinueStatement(p)) return false;
  return true;
}
function tsFiles(dir) {
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const f = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...tsFiles(f));
    else if (f.endsWith(".ts")) out.push(f);
  }
  return out.sort();
}
function moduleSpecifiers(sf) {
  const out = [];
  walk(sf, (node) => {
    if ((ts.isImportDeclaration(node) || (ts.isExportDeclaration(node) && node.moduleSpecifier)) &&
        ts.isStringLiteralLike(node.moduleSpecifier)) out.push([node, node.moduleSpecifier.text]);
    if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword)
      report(sf, node, "dynamic import");
  });
  return out;
}
function layerOf(rel) {
  if (rel === CLI_ENTRY) return "cli";
  const parts = rel.split("/");
  return parts.length >= 3 && parts[0] === "src" ? parts[1] : null;
}

function checkSrc(files) {
  for (const file of files ?? tsFiles("src")) {
    const sf = parse(file);
    const rel = file.split(path.sep).join("/");
    const layer = layerOf(rel);
    if (layer === null && !ROOT_FILES.has(rel)) { bad.push(`guard: ${rel} is not under a layer directory`); continue; }
    if (layer !== null && !(layer in LAYERS)) { bad.push(`guard: ${rel} is in an unknown layer "${layer}"`); continue; }
    const allowed = layer === null ? [] : LAYERS[layer];
    for (const [node, spec] of moduleSpecifiers(sf)) {
      if (spec.startsWith("node:")) {
        if (spec === "node:child_process" && !SHELL.has(layer))
          report(sf, node, `node:child_process outside src/acceptance and src/git`);
        if (spec === "node:child_process" && layer === "git" && rel !== GIT_SPAWNER)
          report(sf, node, `node:child_process in ${rel} (only ${GIT_SPAWNER} spawns git)`);
        continue;
      }
      if (spec === "yaml") { if (!YAML.has(layer)) report(sf, node, `"yaml" outside src/contour`); continue; }
      if (!spec.startsWith("./") && !spec.startsWith("../")) { report(sf, node, `package import "${spec}" (node:* only)`); continue; }
      const target = path.posix.normalize(path.posix.join(path.posix.dirname(rel), spec));
      const tl = layerOf(target);
      if (tl === null) { if (!ROOT_FILES.has(target)) report(sf, node, `import of "${spec}" outside src/<layer>/`); continue; }
      if (tl !== layer && allowed !== "*" && !allowed.includes(tl))
        report(sf, node, `layer ${layer ?? "src"} imports layer ${tl} (allowed: ${allowed.join(", ") || "none"})`);
    }
    walk(sf, (node) => {
      if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
      if (ts.isIdentifier(node) && isValueRef(node)) {
        const n = node.text;
        if (["fetch", "WebSocket", "XMLHttpRequest"].includes(n) && !NET.has(layer))
          report(sf, node, `global ${n} outside src/processor`);
        if (n === "console" && !CONSOLE.has(layer)) report(sf, node, "console outside src/cli");
        if (n === "process" && !PROCESS.has(layer)) report(sf, node, "process outside src/cli, src/processor, src/acceptance");
        if ((n === "process" || n === "console") && layer === "cli" && rel !== CLI_ENTRY)
          report(sf, node, `${n} in ${rel} (only ${CLI_ENTRY} touches it; env, cwd, clock and io are parameters)`);
        if (n === "Date" && NO_CLOCK.has(layer)) report(sf, node, `Date in the deterministic layer ${layer}`);
        if (n === "Math" && node.parent && ts.isPropertyAccessExpression(node.parent) &&
            node.parent.name.text === "random") report(sf, node, "Math.random");
      }
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "exit" && !CONSOLE.has(layer))
        report(sf, node, "process.exit outside src/cli");
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "exit" && rel === CLI_ENTRY)
        report(sf, node, `process.exit in ${CLI_ENTRY} (set process.exitCode: exit cuts a piped stdout)`);
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "Date" && node.name.text === "now" && layer === "cli" && rel !== CLI_ENTRY)
        report(sf, node, `Date.now in ${rel} (the clock is the parameter now)`);
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "env" && NO_ENV.has(layer) &&
          !ENV_READERS.has(rel))
        report(sf, node, `process.env in src/${layer} (the environment is a parameter)`);
    });
  }
}

function checkHelpers(file, names) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const sf = parse(file);
  for (const [node, spec] of moduleSpecifiers(sf))
    if (!spec.startsWith("node:")) report(sf, node, `helpers import "${spec}" (node:* only)`);
  const exported = new Set();
  walk(sf, (node) => {
    if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
    const mods = ts.canHaveModifiers(node) ? ts.getModifiers(node) ?? [] : [];
    if (!mods.some((m) => m.kind === ts.SyntaxKind.ExportKeyword)) return;
    if ((ts.isFunctionDeclaration(node) || ts.isInterfaceDeclaration(node) ||
         ts.isTypeAliasDeclaration(node) || ts.isClassDeclaration(node)) && node.name)
      exported.add(node.name.text);
    if (ts.isVariableStatement(node))
      for (const d of node.declarationList.declarations) if (ts.isIdentifier(d.name)) exported.add(d.name.text);
  });
  for (const n of names) if (!exported.has(n)) bad.push(`guard: ${file} does not export ${n}`);
}

function checkTest(file, min, max, lits) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const sf = parse(file);
  const text = sf.getFullText();
  let count = 0;
  for (const [node, spec] of moduleSpecifiers(sf))
    if (spec !== "vitest" && !spec.startsWith("node:") && !spec.startsWith("./") && !spec.startsWith("../"))
      report(sf, node, `import of a package "${spec}" (vitest, node:* and relative paths only)`);
  walk(sf, (node) => {
    if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
    if (ts.isCallExpression(node) && ts.isIdentifier(node.expression) &&
        (node.expression.text === "test" || node.expression.text === "it")) count += 1;
    if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression)) {
      const o = node.expression.text, p = node.name.text;
      if (["test", "it", "describe"].includes(o) && ["skip", "only", "todo", "fails"].includes(p))
        report(sf, node, `${o}.${p}`);
      if (o === "vi" && ["stubGlobal", "useFakeTimers", "mock", "doMock"].includes(p))
        report(sf, node, `vi.${p} (stubs come from tests/helpers.ts)`);
    }
    if (ts.isIdentifier(node) && isValueRef(node) &&
        ["setTimeout", "setInterval", "setImmediate"].includes(node.text))
      report(sf, node, `${node.text} (real timers are not used under tests/; use fakeClock)`);
    const declared = (ts.isFunctionDeclaration(node) || ts.isVariableDeclaration(node) ||
      ts.isClassDeclaration(node)) && node.name && ts.isIdentifier(node.name) ? node.name.text : null;
    if (declared && (declared === "fetch" || /^[Ff]ake/.test(declared)))
      report(sf, node, `own stub "${declared}" (stubs come from tests/helpers.ts)`);
  });
  if (count < min || count > max)
    bad.push(`guard: ${file} has ${count} test/it calls, expected ${min}..${max}`);
  for (const lit of lits) if (!text.includes(lit)) bad.push(`guard: ${file} does not mention the example literal ${JSON.stringify(lit)}`);
}

const [mode, a, b, c, d] = process.argv.slice(2);
if (mode === "src") checkSrc(a ? a.split(",").filter(Boolean) : null);
else if (mode === "helpers") checkHelpers(a, (b ?? "").split(",").filter(Boolean));
else if (mode === "tests") checkTest(a, Number(b), Number(c), d ? JSON.parse(fs.readFileSync(d, "utf8")) : []);
else bad.push(`guard: unknown mode ${mode}`);
for (const x of bad) console.log(x);
process.exit(bad.length ? 1 : 0);
MORPH_GUARD_EOF
cat > $P/probe.config.mts <<'MORPH_CONF_EOF'
import { defineConfig } from "vitest/config";
import { fileURLToPath } from "node:url";
export default defineConfig({
  root: fileURLToPath(new URL("../..", import.meta.url)),
  test: { environment: "node", include: ["probe/document/**/*.probe.ts"],
    setupFiles: ["tests/setup.ts"], chaiConfig: { truncateThreshold: 200 } },
});
MORPH_CONF_EOF
cat > $P/tsconfig.card.json <<'MORPH_TSCONF_EOF'
{
  "extends": "../../tsconfig.json",
  "include": [
    "../../src",
    "../../tests",
    "./*.probe.ts"
  ]
}
MORPH_TSCONF_EOF
cat > $P/document.probe.ts <<'MORPH_PROBE_EOF'
// P7 probe for document: renderDocument, errorDocument, classifyThrown, runExitCode, readDeckFile by
// docs/TASK_P7_cli.md §2.2, one test per record example (Component cli: Emit Document 1-3, Classify
// Error 1-3, Read Deck File 1-3), then the §2.2 rows and the types.
import { test, expect, expectTypeOf } from "vitest";
import fs from "node:fs";
import { classifyThrown, errorDocument, readDeckFile, renderDocument, runExitCode } from "../../src/cli/document.js";
import type { CommandResult, DeckFileResult, ErrorDocument, ErrorKind, ExitCode } from "../../src/cli/types.js";
import type { CardOutcome, CardStatus, RunReport } from "../../src/runloop/types.js";
import type { ArchiveResult } from "../../src/git/types.js";
import { fixture, tmpRoot } from "../../tests/helpers.js";

const outcome = (customId: string, status: CardStatus): CardOutcome => ({
  customId, status, reason: null, attempts: 1, winningVariant: null, acceptanceLog: "", earlierFailures: [],
  commit: null, diffstat: null,
});
const report = (outcomes: CardOutcome[]): RunReport => ({
  runId: "r1", completedAt: 0, branch: "morph/r1", processor: "s", generations: 1, outcomes,
  usageTotals: { inputTokens: 0, outputTokens: 0, cost: 0, requests: outcomes.length },
});
const archived: ArchiveResult = { ok: true, dir: ".morph/runs/r1", commit: "c".repeat(40) };

test("Emit Document example 1: compact, one line, newline-terminated", () => {
  expect(renderDocument({ a: 1, b: [true, null] }, false)).toBe('{"a":1,"b":[true,null]}\n');
});

test("Emit Document example 2: --pretty indents by 2", () => {
  expect(renderDocument({ a: 1, b: [true, null] }, true)).toBe('{\n  "a": 1,\n  "b": [\n    true,\n    null\n  ]\n}\n');
});

test("Emit Document example 3: an error document, keys code, kind, message", () => {
  const doc = errorDocument(4, "UsageError", "unknown command: x");
  expect(doc).toStrictEqual({ error: { code: 4, kind: "UsageError", message: "unknown command: x" } });
  expect(renderDocument(doc, false)).toBe('{"error":{"code":4,"kind":"UsageError","message":"unknown command: x"}}\n');
});

test("Classify Error example 1: a thrown Error is exit 3, RuntimeError, its message", () => {
  expect(classifyThrown(new Error("git add failed (exit 1): fatal: x"))).toStrictEqual({
    code: 3, document: { error: { code: 3, kind: "RuntimeError", message: "git add failed (exit 1): fatal: x" } },
  });
});

test("Classify Error example 2: a thrown non-Error is String(value)", () => {
  expect(classifyThrown("boom")).toStrictEqual({ code: 3, document: { error: { code: 3, kind: "RuntimeError", message: "boom" } } });
  expect(classifyThrown(42)).toStrictEqual({ code: 3, document: { error: { code: 3, kind: "RuntimeError", message: "42" } } });
});

test("Classify Error example 3: the run's exit code from the report and the archive", () => {
  const rows = [
    runExitCode(report([outcome("a", "written"), outcome("b", "written")]), archived),
    runExitCode(report([outcome("a", "written"), outcome("b", "skipped")]), archived),
    runExitCode(report([outcome("a", "written")]), { ok: false, error: "archive .morph/runs/r1 already exists" }),
  ];
  expect(rows.join(" ")).toBe("0 1 3");
});

test("Read Deck File example 1: a valid deck file", () => {
  const r = tmpRoot();
  try {
    r.write("d.json", fixture("decks/tiny.json"));
    const got = readDeckFile(r.root, "d.json");
    expect(got).toStrictEqual({ ok: true, deck: { cards: [{ customId: "a", intent: "generate", targets: ["src/a.ts"],
      contextSlice: [], instruction: "x", acceptance: null, model: null, maxTokens: null, reasoning: null, variants: 1,
      dependsOn: [] }], externalDependsOn: [] } });
  } finally {
    r.rm();
  }
});

test("Read Deck File example 2: a missing file is exit 4, the path as given", () => {
  const r = tmpRoot();
  try {
    expect(readDeckFile(r.root, "nope.json")).toStrictEqual({ ok: false, result: { code: 4,
      document: { error: { code: 4, kind: "UsageError", message: "deck file not found: nope.json" } } } });
  } finally {
    r.rm();
  }
});

test("Read Deck File example 3: an invalid deck is exit 2, every fault", () => {
  const r = tmpRoot();
  try {
    r.write("c.json", fixture("decks/cycle.json"));
    r.write("dup.json", fixture("decks/duplicate.json"));
    expect(readDeckFile(r.root, "c.json")).toStrictEqual({ ok: false, result: { code: 2,
      document: { error: { code: 2, kind: "DeckError", message: "invalid deck: dependsOn: dependsOn cycle a -> b -> a" } } } });
    expect(readDeckFile(r.root, "dup.json")).toStrictEqual({ ok: false, result: { code: 2,
      document: { error: { code: 2, kind: "DeckError", message: "invalid deck: cards[2].customId: duplicate customId b" } } } });
  } finally {
    r.rm();
  }
});

test("§2.2: several faults joined by '; '; a directory is not a deck file; an absolute path", () => {
  const r = tmpRoot();
  try {
    r.write("bad.json", '[{"customId":"a b"}]');
    const got = readDeckFile(r.root, "bad.json");
    const message = got.ok ? "ok" : JSON.stringify(got.result.document);
    expect(message).toBe(JSON.stringify({ error: { code: 2, kind: "DeckError", message:
      "invalid deck: cards[0].customId: customId 'a b' does not match ^[A-Za-z0-9._-]+$; cards[0].intent: intent is required; "
      + "cards[0].targets: targets is required; cards[0].instruction: instruction is required" } }));
    fs.mkdirSync(r.path("dir.json"));
    const dir = readDeckFile(r.root, "dir.json");
    expect(dir.ok ? "ok" : dir.result.code).toBe(4);
    r.write("t.json", fixture("decks/tiny.json"));
    const abs = readDeckFile("/nonexistent-root", r.path("t.json"));
    expect(abs.ok ? abs.deck.cards.length : -1, "absolute path ignores root").toBe(1);
    const notJson = (() => { r.write("x.json", "{"); const x = readDeckFile(r.root, "x.json"); return x.ok ? "ok" : JSON.stringify(x.result.document); })();
    expect(notJson.startsWith('{"error":{"code":2,"kind":"DeckError","message":"invalid deck: deck: deck is not valid JSON: '), notJson).toBe(true);
  } finally {
    r.rm();
  }
});

test("§2.2: failed and budget-exceeded are exit 1; an empty report with the archive ok is 0", () => {
  expect(runExitCode(report([outcome("a", "failed")]), archived)).toBe(1);
  expect(runExitCode(report([outcome("a", "budget-exceeded")]), archived)).toBe(1);
  expect(runExitCode(report([]), archived)).toBe(0);
  expect(runExitCode(report([outcome("a", "failed")]), { ok: false, error: "x" }), "archive first").toBe(3);
});

test("§2.2: the types", () => {
  expectTypeOf<ExitCode>().toEqualTypeOf<0 | 1 | 2 | 3 | 4>();
  expectTypeOf<ErrorKind>().toEqualTypeOf<"UsageError" | "NotYetError" | "DeckError" | "RefusalError" | "RuntimeError">();
  expectTypeOf<ErrorDocument>().toEqualTypeOf<{ error: { code: ExitCode; kind: ErrorKind; message: string } }>();
  expectTypeOf<CommandResult>().toEqualTypeOf<{ code: ExitCode; document: unknown }>();
  expectTypeOf(renderDocument).toEqualTypeOf<(doc: unknown, pretty: boolean) => string>();
  expectTypeOf(errorDocument).toEqualTypeOf<(code: ExitCode, kind: ErrorKind, message: string) => ErrorDocument>();
  expectTypeOf(classifyThrown).toEqualTypeOf<(e: unknown) => CommandResult>();
  expectTypeOf(runExitCode).toEqualTypeOf<(report: RunReport, archive: ArchiveResult) => ExitCode>();
  expectTypeOf(readDeckFile).toEqualTypeOf<(root: string, deckPath: string) => DeckFileResult>();
});
MORPH_PROBE_EOF
G0=$( (git symbolic-ref -q HEAD || true; git rev-parse HEAD; git for-each-ref --format='%(refname) %(objectname)') 2>&1)
echo '== tsc'; node_modules/.bin/tsc --noEmit -p $P/tsconfig.card.json
echo '== eslint'; node_modules/.bin/eslint src/cli/types.ts src/cli/document.ts
echo '== guard'; node $P/guard.mjs src src/cli/types.ts,src/cli/document.ts
echo '== probe'; node_modules/.bin/vitest run --config $P/probe.config.mts --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== full'; node_modules/.bin/vitest run --passWithNoTests --reporter=dot > $P/vt.log 2>&1 || { grep -E '^ FAIL |Error|AssertionError|^ +Tests |^ +Test Files |expected|received' $P/vt.log | head -80; exit 1; }
echo '== own git'; G1=$( (git symbolic-ref -q HEAD || true; git rev-parse HEAD; git for-each-ref --format='%(refname) %(objectname)') 2>&1); [ "$G0" = "$G1" ] || { echo "tests changed this repository's HEAD or refs:"; echo "before: $G0" | head -5; echo "after: $G1" | head -5; exit 1; }
echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e src/cli/types.ts -e src/cli/document.ts || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc

D=/tmp/morph/deck-check-p7; mkdir -p $D; S=$(date +%s)-$$; L=$D/acc-$S.log
cp src/cli/deckCheck.ts $D/0-$S.ts 2>/dev/null
(
 set -e
 export NO_COLOR=1 CI=1
P=$PWD/probe/deck-check; rm -rf $P; mkdir -p $P; trap 'rm -rf $P' EXIT
cat > $P/guard.mjs <<'MORPH_GUARD_EOF'
// MorphV2 guard: the layer rules of docs/CONVENTIONS.md and the test-file rules, checked on
// the TypeScript syntax tree. Inlined into every acceptance by decks/tools/build.py.
//   node guard.mjs src [file,file,...]                   every .ts under src/, or only these
//   node guard.mjs helpers <file> <name,name,...>        the stub module: node:* only, exports
//   node guard.mjs tests <file> <min> <max> [lits.json]  one test file; lits = strings it must hold
import ts from "typescript";
import fs from "node:fs";
import path from "node:path";

const bad = [];

// which internal layers a layer may import; "*" = any; unknown dirs are reported
const LAYERS = {
  cards: [], wait: [],
  response: ["cards"], store: ["cards"], compiler: ["cards"], language: ["cards"],
  contour: ["cards"], git: ["cards"], acceptance: ["cards", "wait", "compiler"],
